#!/usr/bin/env bash
# What:    {{WHAT}}
# When:    {{WHEN}}
# Env:     {{ENV}}
# Example: {{EXAMPLE}}
#
# Output convention:
#   - stdout (default):  one PASS/FAIL line + path to /tmp log
#   - stdout (--verbose): full log streamed via `tee`
#   - exit code:         0 on PASS, non-zero on FAIL
#
# Generated/maintained via `/script-builder`.

set -euo pipefail

SCRIPT_NAME="{{SCRIPT_NAME}}"
LOG_FILE="/tmp/${SCRIPT_NAME}-$(date +%Y%m%d-%H%M%S).log"
VERBOSE=0
STATUS="fail"
SUMMARY="unknown error"

usage() {
  cat <<EOF
Usage: ${SCRIPT_NAME} [--verbose|-v] [--help|-h]

  --verbose, -v   Stream full log to stdout (default: only PASS/FAIL summary)
  --help, -h      Show this message

What:    {{WHAT}}
When:    {{WHEN}}
Env:     {{ENV}}
Example: {{EXAMPLE}}
EOF
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    -v|--verbose) VERBOSE=1; shift ;;
    -h|--help)    usage; exit 0 ;;
    *) echo "unknown arg: $1" >&2; usage >&2; exit 2 ;;
  esac
done

log() {
  local line
  line="[$(date -u +%Y-%m-%dT%H:%M:%SZ)] $*"
  echo "$line" >>"$LOG_FILE"
  if [[ "$VERBOSE" -eq 1 ]]; then
    echo "$line"
  fi
}

finish() {
  local rc=$?
  if [[ "$rc" -eq 0 && "$STATUS" == "pass" ]]; then
    echo "PASS: ${SUMMARY} (log: ${LOG_FILE})"
    exit 0
  else
    echo "FAIL: ${SUMMARY} (log: ${LOG_FILE})"
    exit $(( rc == 0 ? 1 : rc ))
  fi
}
trap finish EXIT

log "Starting ${SCRIPT_NAME}"

{{TEST_BODY}}

STATUS="pass"
SUMMARY="{{WHAT}}"

#!/usr/bin/env python3
{{UV_METADATA}}
"""
{{WHAT}}

When:    {{WHEN}}
Env:     {{ENV}}
Example: {{EXAMPLE}}

Output convention:
  - stdout (default):  one PASS/FAIL line + path to /tmp log
  - stdout (--verbose): full log streamed
  - stdout (--json):    {"status":"pass"|"fail","log":"<path>","summary":"..."}
  - exit code:         0 on PASS, non-zero on FAIL

Generated/maintained via `/script-builder`.
"""

import argparse
import json as _json
import os
import sys
from datetime import datetime
from pathlib import Path

SCRIPT_NAME = "{{SCRIPT_NAME}}"
TS = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
LOG_PATH = Path(f"/tmp/{SCRIPT_NAME}-{TS}.log")


class TeeLogger:
    """Writes every line to the /tmp log; mirrors to stdout only when --verbose."""

    def __init__(self, log_path: Path, verbose: bool) -> None:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        self._fh = log_path.open("a", buffering=1)
        self._verbose = verbose

    def log(self, msg: str) -> None:
        line = f"[{datetime.utcnow().isoformat()}] {msg}\n"
        self._fh.write(line)
        if self._verbose:
            sys.stdout.write(line)
            sys.stdout.flush()

    def close(self) -> None:
        self._fh.close()


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(
        prog=SCRIPT_NAME,
        description="{{WHAT}}",
        epilog=f"When: {{WHEN}}\nEnv: {{ENV}}\nExample: {{EXAMPLE}}",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    p.add_argument("-v", "--verbose", action="store_true", help="Stream full log to stdout")
    p.add_argument("--json", action="store_true", help="Emit a single JSON summary line")
    return p.parse_args()


def summary(status: str, message: str, json_out: bool) -> int:
    if json_out:
        sys.stdout.write(_json.dumps({"status": status, "log": str(LOG_PATH), "summary": message}) + "\n")
    else:
        tag = "PASS" if status == "pass" else "FAIL"
        sys.stdout.write(f"{tag}: {message} (log: {LOG_PATH})\n")
    return 0 if status == "pass" else 1


def main() -> int:
    args = parse_args()
    logger = TeeLogger(LOG_PATH, args.verbose)
    logger.log(f"Starting {SCRIPT_NAME}")
    try:
        {{TEST_BODY}}
        return summary("pass", "{{WHAT}}", args.json)
    except Exception as err:  # noqa: BLE001 — top-level guard for context-optimal output
        logger.log(f"ERROR: {err!r}")
        return summary("fail", str(err), args.json)
    finally:
        logger.close()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env bun
// Falls back to `npx tsx` or compiled Node if Bun is not installed; see {{EXAMPLE}}.
//
// What:    {{WHAT}}
// When:    {{WHEN}}
// Env:     {{ENV}}
// Example: {{EXAMPLE}}
//
// Output convention:
//   - stdout (default):  one PASS/FAIL line + path to /tmp log
//   - stdout (--verbose): full log streamed
//   - stdout (--json):    {"status":"pass"|"fail","log":"<path>","summary":"..."}
//   - exit code:         0 on PASS, non-zero on FAIL
//
// Generated/maintained via `/script-builder`.

import { appendFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const SCRIPT_NAME = "{{SCRIPT_NAME}}";
const TS = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+/, "").replace("T", "-");
const LOG_PATH = `/tmp/${SCRIPT_NAME}-${TS}.log`;

const args = new Set(process.argv.slice(2));
const VERBOSE = args.has("--verbose") || args.has("-v");
const JSON_OUT = args.has("--json");
const HELP = args.has("--help") || args.has("-h");

if (HELP) {
  console.log(`Usage: ${SCRIPT_NAME} [--verbose] [--json] [--help]

  --verbose, -v   Stream full log to stdout (default: only PASS/FAIL summary)
  --json          Emit a single JSON object with {status, log, summary}
  --help, -h      Show this message

What:    {{WHAT}}
When:    {{WHEN}}
Env:     {{ENV}}
Example: {{EXAMPLE}}
`);
  process.exit(0);
}

mkdirSync(dirname(LOG_PATH), { recursive: true });

function log(msg: string) {
  const line = `[${new Date().toISOString()}] ${msg}\n`;
  appendFileSync(LOG_PATH, line);
  if (VERBOSE) process.stdout.write(line);
}

function summary(status: "pass" | "fail", message: string): never {
  if (JSON_OUT) {
    process.stdout.write(JSON.stringify({ status, log: LOG_PATH, summary: message }) + "\n");
  } else {
    const tag = status === "pass" ? "PASS" : "FAIL";
    process.stdout.write(`${tag}: ${message} (log: ${LOG_PATH})\n`);
  }
  process.exit(status === "pass" ? 0 : 1);
}

async function main() {
  log(`Starting ${SCRIPT_NAME}`);
  try {
    {{TEST_BODY}}
    summary("pass", "{{WHAT}}");
  } catch (err) {
    log(`ERROR: ${err instanceof Error ? err.stack ?? err.message : String(err)}`);
    summary("fail", err instanceof Error ? err.message : String(err));
  }
}

main();

